const campaigns = ['Spring Sale 2024', 'Brand Awareness Q1', 'Retargeting - Cart Abandoners', 'Lookalike - High Value'];
const adSets = ['US - 25-44', 'UK - 25-44', 'CA - All Ages', 'AU - 18-34'];
const placements = ['Feed', 'Stories', 'Reels', 'Audience Network'];
const objectives = ['Conversions', 'Reach', 'Video Views', 'Traffic'];

const rows = [];
const now = new Date();

for (let i = 0; i < 80; i++) {
  const daysAgo = Math.floor(Math.random() * 30);
  const date = new Date(now.getTime() - daysAgo * 86400000);
  const campaign = campaigns[Math.floor(Math.random() * campaigns.length)];
  const adSet = adSets[Math.floor(Math.random() * adSets.length)];
  const placement = placements[Math.floor(Math.random() * placements.length)];
  const objective = objectives[Math.floor(Math.random() * objectives.length)];

  const impressions = Math.floor(Math.random() * 50000 + 5000);
  const reach = Math.floor(impressions * (Math.random() * 0.2 + 0.7));
  const clicks = Math.floor(impressions * (Math.random() * 0.04 + 0.005));
  const spend = parseFloat((Math.random() * 800 + 50).toFixed(2));
  const ctr = parseFloat((clicks / impressions * 100).toFixed(2));
  const cpc = clicks > 0 ? parseFloat((spend / clicks).toFixed(2)) : 0;
  const conversions = Math.floor(clicks * (Math.random() * 0.12 + 0.01));
  const convRate = clicks > 0 ? parseFloat((conversions / clicks * 100).toFixed(2)) : 0;
  const revenue = parseFloat((conversions * (Math.random() * 120 + 30)).toFixed(2));
  const roas = spend > 0 ? parseFloat((revenue / spend).toFixed(2)) : 0;
  const frequency = parseFloat((impressions / reach).toFixed(2));

  rows.push({
    date: date.toISOString().split('T')[0],
    campaign_name: campaign,
    ad_set_name: adSet,
    placement,
    objective,
    impressions,
    reach,
    clicks,
    spend,
    ctr,
    cpc,
    conversions,
    conversion_rate: convRate,
    revenue,
    roas,
    frequency
  });
}

return [{ json: { data: rows, count: rows.length } }];
